SOURCE_INPUTS={'shade': {'sha256': '2050c86562c5bbc3d55db0fc7d8810028d054129aa6ac0a975d77e40770a3345', 'bytes': 12904, 'compressed': ''}, 'tower': {'sha256': '1442b98497f530dcfd82fc093b1cb8cd9e47bfe1e9e7016ba3656bcf970d8c7a', 'bytes': 12457, 'compressed': ''}, 'palm': {'sha256': '1fe785399fa01b958d7ee27ff03ec586b3848638ce8db175efdd3c2c735837f8', 'bytes': 14984, 'compressed': ''}}
